def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 10:
        return 'C'

    opp_d = 0
    for my, opp in history:
        if opp == 'D':
            opp_d += 1

    last_my, last_opp = history[-1]

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    recent10 = history[-10:]
    recent5 = history[-5:]
    recent_opp_d = sum(1 for my, opp in recent10 if opp == 'D')
    recent_opp_d5 = sum(1 for my, opp in recent5 if opp == 'D')
    recent_my_d5 = sum(1 for my, opp in recent5 if my == 'D')

    if opp_d * 100 > n * 42 or recent_opp_d5 >= 4:
        if opp_c_streak >= 4 and recent_opp_d5 == 0 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if opp_d == 0:
        if n >= 16 and last_opp == 'C':
            return 'D'
        return 'C'

    if last_my == 'D' and last_opp == 'C':
        if (opp_d <= max(10, n // 5) and opp_c_streak >= 2 and
                my_d_streak <= 20 and recent_opp_d <= 1):
            return 'D'

    if last_opp == 'C' and recent_opp_d == 0:
        if opp_c_streak >= 25 and opp_d <= max(6, n // 6):
            if n == 60 or rng.random() < 0.015:
                return 'D'
        elif opp_c_streak >= 12 and opp_d <= max(2, n // 12) and n >= 70:
            if rng.random() < 0.05:
                return 'D'

    if (last_opp == 'C' and opp_d * 100 > n * 38 and
            opp_c_streak <= 4 and recent_opp_d <= 2 and recent_my_d5 <= 1):
        return 'D'

    if last_opp == 'D':
        if last_my == 'C' and opp_d * 100 > n * 35 and recent_opp_d >= 2:
            return 'D'

        if opp_d * 100 <= n * 40:
            if opp_d_streak >= 2:
                if last_my == 'D':
                    if rng.random() < 0.65:
                        return 'C'
                    return 'D'
                else:
                    if rng.random() < 0.70:
                        return 'D'
                    return 'C'

            if opp_d_streak == 1:
                if opp_d <= max(2, n // 8) or (n >= 2 and history[-2][0] == 'D'):
                    return 'C'
                return 'D'

        if opp_c_streak >= 5 and recent_opp_d5 == 0 and rng.random() < 0.3:
            return 'C'
        return 'D'

    if opp_d <= max(2, n // 8) and opp_c_streak >= 20 and rng.random() < 0.005:
        return 'D'

    return 'C'
